/**
 * Chat-Bot knowledge base from the code (docs/chatbot-wissensbasis.html, generated by
 * `npm run wissensbasis` from src/lib/anleitung + field reference) instead of the Prismic field
 * «Chat-Bot Wissensbasis». Only where slicemachine.config.json sets `"chatKnowledgeFromCode": true`
 * (klap-web-ch) — other websites write their own knowledge base in Prismic.
 *
 * The file is bundled into the server function (never public) as a lazy chunk, loaded only when
 * the switch is on. Every deploy brings the current version; nothing to copy into Prismic.
 */
import config from '../../../slicemachine.config.json';

export const CHAT_KNOWLEDGE_FROM_CODE =
	(config as { chatKnowledgeFromCode?: boolean }).chatKnowledgeFromCode === true;

const loaders = import.meta.glob('../../../docs/chatbot-wissensbasis.html', {
	query: '?raw',
	import: 'default'
});

let cached: string | null = null;

/** Knowledge base text for the model, '' when the switch is off or the file is missing */
export async function codeKnowledgeBase(): Promise<string> {
	if (!CHAT_KNOWLEDGE_FROM_CODE) return '';
	if (cached !== null) return cached;
	const load = Object.values(loaders)[0];
	cached = load ? htmlToKnowledge((await load()) as string) : '';
	return cached;
}

const ENTITIES: Record<string, string> = {
	'&amp;': '&',
	'&lt;': '<',
	'&gt;': '>',
	'&quot;': '"',
	'&#39;': "'",
	'&nbsp;': ' '
};

/**
 * HTML → Markdown-like text, same shape as the Prismic rich text (richTextToMarkdown in
 * /api/chat): headings as #, list items as «- », one block per line
 */
export function htmlToKnowledge(html: string): string {
	const body = /<body[^>]*>([\s\S]*)<\/body>/i.exec(html)?.[1] ?? html;
	return (
		body
			.replace(/<!--[\s\S]*?-->/g, '')
			.replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, '')
			.replace(/<h([1-6])[^>]*>/gi, (_, level) => `\n${'#'.repeat(Number(level) - 1 || 1)} `)
			.replace(/<li[^>]*>/gi, '- ')
			.replace(/<\/(h[1-6]|p|li|ul|ol)>/gi, '\n')
			.replace(/<br\s*\/?>/gi, '\n')
			.replace(/<[^>]+>/g, '')
			.replace(/&[a-z#0-9]+;/gi, (entity) => ENTITIES[entity] ?? entity)
			.split('\n')
			.map((line) => line.trim())
			.filter((line, i, lines) => line || (lines[i - 1] ?? '') !== '')
			.join('\n')
			// list items directly below each other
			.replace(/\n\n(?=- )/g, '\n')
			.trim()
	);
}
